SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(s),'relation',to_jsonb(pg_identify_object('pg_class'::regclass,s.seqrelid,0)),'type',to_jsonb(pg_identify_object('pg_type'::regclass,s.seqtypid,0))) ORDER BY s.seqrelid),'[]'::jsonb) AS payload FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid WHERE c.relnamespace='public'::regnamespace) AS capture